dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "type": "input multiple",
      "parameter": "genes",
      "label": "Genes(PPARG,PCSK9,SLC30A8)"
    },
{
      "parameter": "region",
      "label": "Region(chr:start-end or gene)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true"
    }
  ],
  "sections": [
    {
      "section id": "genes_summary",
      "header": "genes summary",
      "data point": {
        "type": "bioindex multiple",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/exrna-biofluid-gene-counts?q=$genes",
        "parameters": [
          "genes"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "example": {
        "gene_symbol": "ABCD4",
        "gene_type": "transcript_CDS",
        "N_exGLs": "12",
        "Biofluid": "plasma"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene_symbol"
          },
          {
            "type": "raw",
            "field name": "Gene type",
            "raw field": "gene_type"
          },
          {
            "type": "raw",
            "field name": "Number of exGLs",
            "raw field": "N_exGLs"
          },
          {
            "type": "raw",
            "field name": "Biofluid",
            "raw field": "Biofluid"
          },
          {
            "type": "join multi",
            "field name": "ExGLs",
            "fields to join": [
              "Biofluid",
              "Gene",
              "Gene type"
            ],
            "join by": [
              ",",
              ","
            ]
          }
        ],
        "top rows": [
          "Gene",
          "Biofluid",
          "Number of exGLs",
          "Gene type",
          "ExGLs"
        ],
        "column formatting": {
          "ExGLs": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "exrna-biofluid-gene",
                "parameters": [
                  "biofluid",
                  "gene"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "replace characters",
                    "field name": "CHR",
                    "raw field": "chr",
                    "replace": [
                      {
                        "from": "chr",
                        "to": ""
                      }
                    ]
                  },
                  {
                    "type": "join multi",
                    "field name": "Region",
                    "fields to join": [
                      "CHR",
                      "start_new",
                      "end_new"
                    ],
                    "join by": [
                      ":",
                      "-"
                    ]
                  },
                  {
                    "type": "join multi",
                    "field name": "start-end",
                    "fields to join": [
                      "start_new",
                      "end_new"
                    ],
                    "join by": [
                      "-"
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "exGLid",
                    "raw field": "exGLid"
                  },
                  {
                    "type": "raw",
                    "field name": "Biofluid",
                    "raw field": "BIOFLUID"
                  },
                  {
                    "type": "raw",
                    "field name": "exRNA Atlas Datasets",
                    "raw field": "DATASETS"
                  },
                  {
                    "type": "raw",
                    "field name": "Read depth (normalized)",
                    "raw field": "Normalized_Read_Depth"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene_name",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene type",
                    "raw field": "gene_type",
                    "if no value": "N/A"
                  },
                  {
                    "type": "raw",
                    "field name": "ENCODE(reg.element)",
                    "raw field": "ENCODE(reg.element)"
                  },
                  {
                    "type": "raw",
                    "field name": "LINE/SINE(repeat_name:class)",
                    "raw field": "LINE/SINE(repeat_name:class)"
                  },
                  {
                    "type": "calculate",
                    "field name": "Position",
                    "expression": [
                      "start_new",
                      "+",
                      "(",
                      "+",
                      "end_new",
                      "-",
                      "start_new",
                      ")",
                      "/",
                      2
                    ],
                    "calculation type": "math"
                  }
                ],
                "top rows": [
                  "Region",
                  "exGLid",
                  "Biofluid",
                  "Gene",
                  "Gene type",
                  "exRNA Atlas Datasets",
                  "Read depth (normalized)",
                  "ENCODE(reg.element)",
                  "LINE/SINE(repeat_name:class)"
                ],
                "tool tips": {
                  "Region": "GRCh37 (hg19) chromosomal coordinate for each exGL.",
                  "exGLid": "Unique ID for each exGL.",
                  "Biofluid": "Biofluid(s) in which the extracellular RNAs mapping to the exGL were detected.",
                  "Gene": "Gene overlapping with the exGL. Gene annotations are consistent with <a href='https://ftp.ebi.ac.uk/pub/databases/gencode/Gencode_human/release_47/gencode.v47.annotation.gtf.gz'>GENCODE v.47</a>.",
                  "Gene type": "Gene type of the gene overlapping with the exGL. Gene types are consistent with GENCODE v.47 annotations, with one exception: 'protein-coding' gene overlaps were split into transcript_CDS (CDS overlaps) and transcript non_CDS (introns,UTR overlaps).",
                  "exRNA Atlas Datasets": "exGLs were created with reads from small-RNA sequencing datasets submitted to the <a href='https://exrna-atlas.org/ftps/exRNA-atlas/AtlasV3.0_data/'>exRNA Atlas</a>. This column contains exRNA Atlas datasets with reads mapping to the exGL.",
                  "Read depth (normalized)": "The normalized read depth values calculated for each biofluid is an estimate of the number of exRNA reads mapping to each exGL. Note that the read depth values are not comparable across biofluids.",
                  "ENCODE(reg.element)": "Regulatory element(s) overlapping with the exGL. Regulatory element IDs consistent with <a href='https://screen.encodeproject.org/'>https://screen.encodeproject.org/</a>, for example EH38E1613479.",
                  "LINE/SINE(repeat_name:class)": "LINE/SINE repeat regions mapping to each biofluid. LINE/SINE repeat annotations were retrieved from <a href='http://hgdownload.soe.ucsc.edu/goldenPath/hg38/bigZips/latest/hg38.fa.out.gz'>UCSC genome browser</a>."
                }
              },
              "visualizer": {
                "label": "",
                "type": "region track",
                "zoom": "true",
                "render by": "start-end",
                "x axis field": "Position",
                "y axis field": "Biofluid",
                "hover content": [
                  "Region",
                  "exGLid",
                  "Biofluid",
                  "Gene",
                  "Gene type",
                  "Datasets",
                  "Read depth (normalized)",
                  "ENCODE(reg.element)",
                  "LINE/SINE(repeat_name:class)"
                ],
                "color by": "Gene type",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genes track": {
                  "input type": "field",
                  "field name": "Gene",
                  "convert to region": true
                }
              }
            }
          }
        }
      },
      "filters": [
        {
          "field": "Gene",
          "label": "Gene",
          "type": "checkbox"
        },
        {
          "field": "Gene type",
          "label": "Gene type",
          "type": "checkbox"
        },
        {
          "field": "Biofluid",
          "label": "Biofluid",
          "type": "checkbox"
        },
        {
          "field": "Number of exGLs",
          "label": "Number of exGLs",
          "type": "search greater than"
        }
      ]
    },
    {
      "section id": "exRnaBioFluids",
      "header": "region search",
      "data point": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/exrna-regions?q=$region&limit=10000",
        "continue url": "https://cfde-dev.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
        "parameters": [
          "region"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chr",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "start-end",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "exGLid",
            "raw field": "exGLid"
          },
          {
            "type": "raw",
            "field name": "Biofluid",
            "raw field": "BIOFLUID"
          },
          {
            "type": "raw",
            "field name": "exRNA Atlas Datasets",
            "raw field": "DATASETS"
          },
          {
            "type": "raw",
            "field name": "Read depth (normalized)",
            "raw field": "Normalized_Read_Depth"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene_name",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Gene type",
            "raw field": "gene_type",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "ENCODE(reg.element)",
            "raw field": "ENCODE(reg.element)"
          },
          {
            "type": "raw",
            "field name": "LINE/SINE(repeat_name:class)",
            "raw field": "LINE/SINE(repeat_name:class)"
          },
          {
            "type": "calculate",
            "field name": "Position",
            "expression": [
              "start",
              "+",
              "(",
              "+",
              "end",
              "-",
              "start",
              ")",
              "/",
              2
            ],
            "calculation type": "math"
          }
        ],
        "top rows": [
          "Region",
          "exGLid",
          "Biofluid",
          "Gene",
          "Gene type",
          "exRNA Atlas Datasets",
          "Read depth (normalized)",
          "ENCODE(reg.element)",
          "LINE/SINE(repeat_name:class)"
        ],
        "tool tips": {
          "Region": "GRCh37 (hg19) chromosomal coordinate for each exGL.",
          "exGLid": "Unique ID for each exGL.",
          "Biofluid": "Biofluid(s) in which the extracellular RNAs mapping to the exGL were detected.",
          "Gene": "Gene overlapping with the exGL. Gene annotations are consistent with <a href='https://ftp.ebi.ac.uk/pub/databases/gencode/Gencode_human/release_47/gencode.v47.annotation.gtf.gz'>GENCODE v.47</a>.",
          "Gene type": "Gene type of the gene overlapping with the exGL. Gene types are consistent with GENCODE v.47 annotations, with one exception: 'protein-coding' gene overlaps were split into transcript_CDS (CDS overlaps) and transcript non_CDS (introns,UTR overlaps).",
          "exRNA Atlas Datasets": "exGLs were created with reads from small-RNA sequencing datasets submitted to the <a href='https://exrna-atlas.org/ftps/exRNA-atlas/AtlasV3.0_data/'>exRNA Atlas</a>. This column contains exRNA Atlas datasets with reads mapping to the exGL.",
          "Read depth (normalized)": "The normalized read depth values calculated for each biofluid is an estimate of the number of exRNA reads mapping to each exGL. Note that the read depth values are not comparable across biofluids.",
          "ENCODE(reg.element)": "Regulatory element(s) overlapping with the exGL. Regulatory element IDs consistent with <a href='https://screen.encodeproject.org/'>https://screen.encodeproject.org/</a>, for example EH38E1613479.",
          "LINE/SINE(repeat_name:class)": "LINE/SINE repeat regions mapping to each biofluid. LINE/SINE repeat annotations were retrieved from <a href='http://hgdownload.soe.ucsc.edu/goldenPath/hg38/bigZips/latest/hg38.fa.out.gz'>UCSC genome browser</a>."
        }
      },
      "filters": [
        {
          "field": "Biofluid",
          "label": "Biofluid",
          "type": "checkbox"
        },
        {
          "field": "exGLid",
          "label": "exGLid",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Datasets",
          "label": "exRNA Atlas Datasets",
          "type": "search"
        },
        {
          "field": "Gene",
          "label": "Gene",
          "type": "checkbox"
        },
        {
          "field": "Gene type",
          "label": "Gene type",
          "type": "checkbox"
        },
        {
          "field": "ENCODE(reg.element)",
          "label": "ENCODE(reg.element)",
          "type": "search"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "region track",
        "zoom": "true",
        "render by": "start-end",
        "x axis field": "Position",
        "y axis field": "Biofluid",
        "hover content": [
          "Region",
          "exGLid",
          "Biofluid",
          "Gene",
          "Gene type",
          "Datasets",
          "Read depth (normalized)",
          "ENCODE(reg.element)",
          "LINE/SINE(repeat_name:class)"
        ],
        "color by": "Gene type",
        "track height": 12,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        }
      }
    }
  ]
}

pageStyle:
.research-narrative-options {
    /*margin-left: -100%  !important;*/
}

.text-align-center{
   text-align:center;
}
.fixed-header {
 position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { 
/* background: none !important;
  border: none; */ }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { /*display: none;*/}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  /* background: none;
  border: none; */
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  /*margin: 0 0 20px 0;*/
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

